cd __RIG_HOME__/research/base-edit-immune-aging && python3 - <<'EOF'
import json
for f in ["search-q1-baseediting-immune-aging.json","search-q2-senescence-immune.json","search-q3-baseediting-immunogenicity.json","search-q4-rigor-replication.json"]:
    d = json.load(open(f))
    calls = d.get("provenance", {}).get("calls", [])
    print("==", f, "| accessed:", d.get("provenance", {}).get("accessed"))
    for c in calls:
        print("   endpoint:", c.get("endpoint"))
        params = {k: v for k, v in (c.get("parameters") or {}).items() if k in ("term", "retmax")}
        print("   params:", params)
        for k, v in c.items():
            if k not in ("endpoint", "parameters"):
                print("  ", k, "=", v)
EOF

